# -*- coding: utf-8 -*-
"""专项普查：frontmatter 字段的「类型」是否符合规范。

A13 批发现 2 页的 `authors` 被写成**单个纯字符串**（而非 YAML 列表），
Obsidian Bases / 检索层因此读不到作者列表。

本脚本检查常见列表型字段是否被误写成标量：
    authors / aliases / tags / sources

用法:
    python tools/qc_schema_check.py              # 普查并写清单
    python tools/qc_schema_check.py --selftest   # 校验器自检
"""
import sys, os, re, glob, json, argparse

try:
    sys.stdout.reconfigure(encoding="utf-8")
except Exception:
    pass

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, qc_work_dir  # noqa: E402

import yaml

LIST_FIELDS = ["authors", "aliases", "tags", "sources"]


def classify(fm):
    """返回 (bad_entries, n_ok)：列表型字段被写成标量的条目。"""
    bad, n_ok = [], 0
    for k in LIST_FIELDS:
        if k not in fm:
            continue
        v = fm[k]
        if isinstance(v, str):
            bad.append((k, v[:80]))
        else:
            n_ok += 1
    return bad, n_ok


def scan():
    bad, n_ok = [], 0
    for f in sorted(glob.glob("wiki/**/*.md", recursive=True)):
        if "/.index/" in f.replace(os.sep, "/"):
            continue
        t = read_text(f)
        if not t.startswith("---"):
            continue
        i = t.find("\n---", 3)
        if i < 0:
            continue
        try:
            fm = yaml.safe_load(t[3:i])
        except Exception:
            continue
        if not isinstance(fm, dict):
            continue
        b, n = classify(fm)
        n_ok += n
        for k, v in b:
            bad.append({"page": os.path.basename(f)[:-3],
                        "rel": os.path.relpath(f, ".").replace(os.sep, "/"),
                        "field": k, "value_head": v})
    return bad, n_ok


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    按本库纪律，反例必须包含「正当的撇号姓名」与「list 型正常值」。
    """
    ok = True
    # 正例：标量 authors 必须被判为坏
    b, n = classify({"authors": "A B and C D"})
    got = len(b) == 1 and b[0][0] == "authors"
    print(f"  [{'ok' if got else 'FAIL'}] 正例 标量 authors 判坏 -> {b}")
    ok = ok and got
    # 反例：list 型必须**不**被判坏
    b, n = classify({"authors": ["A B", "C D"], "tags": [1, 2]})
    got = len(b) == 0 and n == 2
    print(f"  [{'ok' if got else 'FAIL'}] 反例 list 型不判坏 -> bad={len(b)} ok={n}")
    ok = ok and got
    # 反例：含正当撇号的姓名（D'Souza / Gryn'ova / Xian'an Jin）在 list 里不得判坏
    b, n = classify({"authors": ["D'Souza A", "Gryn'ova G", "Xian'an Jin"]})
    got = len(b) == 0
    print(f"  [{'ok' if got else 'FAIL'}] 反例 正当撇号姓名不判坏")
    ok = ok and got
    # 反例：字段不存在时既不判坏也不计入 ok
    b, n = classify({})
    got = len(b) == 0 and n == 0
    print(f"  [{'ok' if got else 'FAIL'}] 反例 字段缺失不计入")
    ok = ok and got
    # 正例：真实库扫描跑通
    bad, n_ok = scan()
    print(f"  [info] 全库扫描 -> 坏 {len(bad)} 处 / 正常 {n_ok} 处")
    # 正例：写盘目标在库根、未落归档
    wd = qc_work_dir(create=True)
    safe = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if safe else 'FAIL'}] 写盘目标在库根、未落归档 -> {wd}")
    ok = ok and safe
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="frontmatter 列表型字段类型核查")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    bad, n_ok = scan()

    print("🔴 列表型字段被误写成「纯字符串」的页面: %d" % len(bad))
    import collections
    c = collections.Counter(b["field"] for b in bad)
    for k, v in c.items():
        print("     %s: %d 处" % (k, v))
    print()
    for b in bad[:60]:
        print("   [%s] %s" % (b["field"], b["page"]))
        print("        %s" % b["value_head"])
    if len(bad) > 60:
        print("   ... 另有 %d 处" % (len(bad) - 60))
    print("\n✅ 类型正确的列表字段: %d 处" % n_ok)
    out = os.path.join(qc_work_dir(create=True), "schema_check.json")
    json.dump(bad, open(out, "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print("清单 -> %s" % out)
    return 0


if __name__ == "__main__":
    sys.exit(main())
